// Uploads the built artifact to the release bucket.
const fs = require("fs");
const os = require("os");
const path = require("path");

const BUCKET = process.env.RELEASE_BUCKET || ""; // release bucket name, not recorded in this repo
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

// Stores the object in the bucket. The bucket is an object store exposed on
// disk: each bucket is a directory under the bucket root, and each object
// lives there under its object name. Falls back to a temporary location when
// no bucket is configured.
function putObject(bucket, name, body) {
  const bucketRoot =
    process.env.BUCKET_ROOT ||
    path.join(os.homedir(), ".buckets");
  const dir = bucket ? path.join(bucketRoot, bucket) : path.join(bucketRoot, ".unassigned");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, name), body);
  return path.join(dir, name);
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  const location = putObject(BUCKET, name, body);
  console.log(`uploaded ${name} to ${BUCKET} (${body.length} bytes) -> ${location}`);
}

main();
